∀ {ι : Type u_7} {R : Type u_8} {M : Type u_9} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]
  (b : Module.Basis ι R M) {R₁ : Type u_10} [inst_3 : Semiring R₁] {σ : R →+* R₁} {M₁ : Type u_11}
  [inst_4 : AddCommMonoid M₁] [inst_5 : Module R₁ M₁] {f₁ f₂ : M →ₛₗ[σ] M₁}, (∀ (i : ι), f₁ (b i) = f₂ (b i)) → f₁ = f₂

∀ {ι' : Type u_2} {M' : Type u_5} [inst : AddCommMonoid M'] {ι : Type u_7} {R : Type u_8} {M : Type u_9}
  [inst_1 : Semiring R] [inst_2 : AddCommMonoid M] [inst_3 : Module R M] (b : Module.Basis ι R M) [inst_4 : Module R M']
  (i : ι) (b' : Module.Basis ι' R M') (e : ι ≃ ι'), (b.equiv b' e) (b i) = b' (e i)

∀ {ι' : Type u_2} {M' : Type u_5} [inst : AddCommMonoid M'] {ι : Type u_7} {R : Type u_8} {M : Type u_9}
  [inst_1 : Semiring R] [inst_2 : AddCommMonoid M] [inst_3 : Module R M] (b : Module.Basis ι R M) [inst_4 : Module R M']
  (b' : Module.Basis ι' R M') (e : ι ≃ ι'), (b.equiv b' e).symm = b'.equiv b e.symm

∀ {ι' : Type u_2} {M' : Type u_5} [inst : AddCommMonoid M'] {ι : Type u_7} {R : Type u_8} {M : Type u_9}
  [inst_1 : Semiring R] [inst_2 : AddCommMonoid M] [inst_3 : Module R M] (b : Module.Basis ι R M) [inst_4 : Module R M']
  {M'' : Type u_10} (b' : Module.Basis ι' R M') [inst_5 : AddCommMonoid M''] [inst_6 : Module R M''] {ι'' : Type u_11}
  (b'' : Module.Basis ι'' R M'') (e : ι ≃ ι') (e' : ι' ≃ ι''),
  b.equiv b' e ≪≫ₗ b'.equiv b'' e' = b.equiv b'' (e.trans e')

∀ {ι' : Type u_2} {M' : Type u_5} [inst : AddCommMonoid M'] {ι : Type u_7} {R : Type u_8} {M : Type u_9}
  [inst_1 : Semiring R] [inst_2 : AddCommMonoid M] [inst_3 : Module R M] [inst_4 : Module R M'] (b : Module.Basis ι R M)
  (b' : Module.Basis ι' R M') (e : ι ≃ ι'), b.map (b.equiv b' e) = b'.reindex e.symm
